18		<style>
19			:root {
20				color-scheme: light dark;
21				--text: #1a1a1a;
22				--text-secondary: #555;
23				--background: #fff;
24				--surface: #fff;
25				--accent: #0052a3;
26				--border: #e0e0e0;
27				--border-control: #767676;
28				--error: #c62828;
29			}
30			@media (prefers-color-scheme: dark) {
31				:root {
32					--text: #e0e0e0;
33					--text-secondary: #a0a0a0;
34					--background: #121212;
35					--surface: #1e1e1e;
36					--accent: #5fa3ff;
37					--border: #333;
38					--border-control: #8c8c8c;
39					--error: #ff8a80;
40				}
41			}
42			*,
43			*::before,
44			*::after {
45				box-sizing: border-box;
46			}
47			html {
48				-webkit-text-size-adjust: 100%;
49				text-size-adjust: 100%;
50			}
51			@media (prefers-reduced-motion: no-preference) {
52				html {
53					scroll-behavior: smooth;
54				}
55				a {
56					transition: text-decoration-thickness 0.15s ease;
57				}
58				.skip-link {
59					transition: transform 0.15s ease;
60				}
61				button,
62				.button {
63					transition: filter 0.15s ease, transform 0.15s ease;
64				}
65			}
66			body {
67				display: grid;
68				grid-template-columns: minmax(0, 1fr);
69				grid-template-rows: auto 1fr auto;
70				min-height: 100vh;
71				min-height: 100dvh;
72				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
73				font-size: 1rem;
74				line-height: 1.6;
75				overflow-wrap: break-word;
76				max-width: 70ch;
77				margin: 0 auto;
78				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
79				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
80				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
81				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
82				color: var(--text);
83				background: var(--background);
84			}
85			h1 {
86				color: var(--accent);
87				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
88				font-weight: 700;
89				line-height: 1.1;
90				text-wrap: balance;
91				margin: 0 0 1.5rem 0;
92				letter-spacing: -0.02em;
93			}
94			h2 {
95				color: var(--accent);
96				font-size: clamp(1.25rem, 1rem + 1.5vw, 1.75rem);
97				font-weight: 600;
98				line-height: 1.2;
99				text-wrap: balance;
100				margin: 2rem 0 1rem 0;
101				letter-spacing: -0.01em;
102			}
103			h2:first-child {
104				margin-top: 0;
105			}
106			p {
107				text-wrap: pretty;
108				margin: 1rem 0;
109				line-height: 1.65;
110			}
111			a {
112				color: var(--accent);
113				text-underline-offset: 0.2em;
114				text-decoration-thickness: 2px;
115				text-decoration-skip-ink: auto;
116				font-weight: 500;
117			}
118			a:hover, a:active {
119				text-decoration-thickness: 3px;
120			}
121			button,
122			.button {
123				display: inline-block;
124				text-decoration: none;
125				padding: 0.75rem 1.5rem;
126				font-size: 1rem;
127				font-weight: 500;
128				font-family: inherit;
129				color: var(--background);
130				background: var(--accent);
131				border: 2px solid var(--accent);
132				border-radius: 0.25rem;
133				cursor: pointer;
134				white-space: nowrap;
135			}
136			button:hover,
137			.button:hover {
138				filter: brightness(1.15);
139				text-decoration: none;
140			}
141			button:active,
142			.button:active {
143				transform: scale(0.97);
144			}
145			ul, ol {
146				margin: 1rem 0;
147				padding-left: 2rem;
148			}
149			li {
150				margin: 0.5rem 0;
151			}
152			:focus-visible {
153				outline: 2px solid var(--accent);
154				outline-offset: 2px;
155			}
156			a:not(.button):focus-visible {
157				border-radius: 2px;
158			}
159			.skip-link {
160				position: absolute;
161				left: 0;
162				top: 0;
163				transform: translateY(-100%);
164				background: var(--accent);
165				color: var(--background);
166				padding: 0.75rem 1.5rem;
167				z-index: 1000;
168				border-radius: 0 0 0.25rem 0;
169				font-weight: 600;
170				text-decoration: none;
171				display: inline-block;
172			}
173			.skip-link:focus {
174				transform: translateY(0);
175				outline: 3px solid var(--text);
176				outline-offset: -3px;
177			}
178			header {
179				padding-block: 1.5rem 0;
180			}
181			nav ul {
182				display: flex;
183				flex-wrap: wrap;
184				gap: 0.5rem 1.5rem;
185				margin: 1rem 0 0 0;
186				padding: 0;
187				list-style: none;
188			}
189			nav li {
190				margin: 0;
191			}
192			footer nav ul {
193				justify-content: center;
194				margin: 0 0 1rem 0;
195			}
196			main {
197				padding: 1rem 0;
198			}
199			main:focus {
200				outline: none;
201			}
202			section {
203				margin: 2rem 0;
204			}
205			[id] {
206				scroll-margin-top: 1.5rem;
207			}
208			@media (forced-colors: active) {
209				.skip-link,
210				button,
211				.button {
212					border: 2px solid ButtonText;
213				}
214			}
215			.card {
216				border: 1px solid var(--border);
217				border-radius: 0.5rem;
218				padding: 1.5rem;
219				background: var(--surface);
220				margin: 1.5rem 0;
221			}
222			.card h3 {
223				font-size: 1.25rem;
224				line-height: 1.3;
225				text-wrap: balance;
226				margin-top: 0;
227				margin-bottom: 0.5rem;
228				color: var(--accent);
229			}
230			.visually-hidden {
231				position: absolute;
232				width: 1px;
233				height: 1px;
234				margin: -1px;
235				padding: 0;
236				overflow: hidden;
237				clip: rect(0, 0, 0, 0);
238				white-space: nowrap;
239				border: 0;
240			}
241			@media (prefers-contrast: more) {
242				:root {
243					--border: currentColor;
244					--border-control: currentColor;
245				}
246				button,
247				.button {
248					border-width: 3px;
249				}
250				.card {
251					border-width: 2px;
252				}
253			}
254			footer {
255				padding-block: 1.5rem;
256				border-top: 1px solid var(--border);
257				font-size: 0.875rem;
258				color: var(--text-secondary);
259				text-align: center;
260			}
261			footer p {
262				margin: 0.5rem 0;
263			}
264			small {
265				display: block;
266			}
267			kbd {
268				background: var(--surface);
269				border: 1px solid var(--border);
270				border-radius: 0.25rem;
271				padding: 0.125rem 0.375rem;
272				font-family: monospace;
273				font-size: 0.875em;
274			}
275			.field {
276				margin-bottom: 1rem;
277			}
278			label {
279				display: block;
280				margin-bottom: 0.5rem;
281				font-weight: 500;
282			}
283			input,
284			textarea {
285				width: 100%;
286				padding: 0.5rem;
287				font: inherit;
288				color: var(--text);
289				background: var(--surface);
290				border: 1px solid var(--border-control);
291				border-radius: 0.25rem;
292			}
293			textarea {
294				resize: vertical;
295			}
296			#form-status:empty {
297				margin: 0;
298			}
299			.form-hint {
300				margin: 0 0 1rem 0;
301				font-size: 0.875rem;
302				color: var(--text-secondary);
303			}
304			.field .form-hint {
305				margin: 0.25rem 0 0 0;
306			}
307			input:user-invalid,
308			textarea:user-invalid,
309			[aria-invalid="true"] {
310				border-color: var(--error);
311				box-shadow: inset 0 0 0 1px var(--error);
312			}
313			.error-message {
314				display: block;
315				color: var(--error);
316				font-size: 0.875rem;
317				font-weight: 500;
318				margin-top: 0.25rem;
319			}
320			.error-message:empty {
321				display: none;
322			}
323			.live-region {
324				display: flex;
325				align-items: center;
326				min-height: 3.5rem;
327				margin-top: 1rem;
328				padding: 1rem;
329				border: 1px dashed var(--border);
330				border-radius: 0.25rem;
331			}
332			input:focus,
333			textarea:focus {
334				outline: 2px solid var(--accent);
335				outline-offset: 2px;
336				border-color: var(--accent);
337			}
338			@media print {
339				:root {
340					color-scheme: light;
341					--text: #000;
342					--text-secondary: #333;
343					--background: #fff;
344					--surface: #fff;
345					--accent: #000;
346					--border: #999;
347					--border-control: #000;
348					--error: #000;
349				}
350				.skip-link,
351				nav,
352				button,
353				.button,
354				.live-region {
355					display: none;
356				}
357				body {
358					display: block;
359					min-height: 0;
360					max-width: none;
361					padding: 0;
362				}
363				a {
364					color: inherit;
365					text-decoration: underline;
366				}
367				a[href^="http"]::after {
368					content: " (" attr(href) ")";
369					font-size: 0.85em;
370					font-weight: normal;
371				}
372				.card {
373					border: none;
374					break-inside: avoid;
375				}
376			}
377		</style>
378	</head>
379	<body>
380		<a class="skip-link" href="#main">Skip to content</a>
381		<header id="top">
382			<h1>Welcome</h1>
383			<nav aria-label="Page sections">
384				<ul>
385					<li><a href="#features">Features</a></li>
386					<li><a href="#examples">Examples</a></li>
387					<li><a href="#resources">Resources</a></li>
388				</ul>
389			</nav>
390		</header>
391		<main id="main" tabindex="-1">
392			<section aria-label="Introduction">
393				<p>This is a well-structured, accessible HTML5 document demonstrating modern best practices for semantic markup and inclusive design.</p>
394				<p>
395					It uses semantic landmarks, a skip link for keyboard navigation,
396					and CSS that adapts to your light or dark mode preference.
397				</p>
398				<p>
399					Text and link colors meet WCAG AA contrast in both themes, type scales
400					with your browser's font size, and motion respects your system settings.
401				</p>
402			</section>
403	
404			<section aria-labelledby="features">
405				<h2 id="features">Features</h2>
406				<ul>
407					<li>Semantic HTML structure with proper landmarks</li>
408					<li>Keyboard accessible navigation and focus management</li>
409					<li>Dark mode support with custom color schemes</li>
410					<li>Responsive typography using modern CSS</li>
411					<li>Print-friendly styles for better readability</li>
412					<li>WCAG AA contrast compliance in all color modes</li>
413				</ul>
414			</section>
415	
416			<section aria-labelledby="examples">
417				<h2 id="examples">Examples</h2>
418				<article class="card">
419					<h3>Component Cards</h3>
420					<p>Card components are useful for organizing related content. They include a subtle border and padding for visual separation.</p>
421					<a class="button" href="#resources">Learn more<span class="visually-hidden"> about accessibility resources</span></a>
422				</article>
423	
424				<article class="card">
425					<h3>Interactive Elements</h3>
426					<p>Buttons and links are fully accessible with clear focus states. All interactive elements include visible focus indicators and proper ARIA labels.</p>
427					<p><strong>Keyboard navigation:</strong> Use <kbd>Tab</kbd> to move forward, <kbd>Shift+Tab</kbd> to move backward, and <kbd>Enter</kbd> to activate.</p>
428				</article>
429	
430				<article class="card">
431					<h3>Accessible Form</h3>
432					<form id="contact-form" novalidate>
433						<p class="form-hint">Fields marked * are required.</p>
434						<div class="field">
435							<label for="email">Email <span aria-hidden="true">*</span></label>
436							<input type="email" id="email" name="email" autocomplete="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
437							<span id="email-error" class="error-message"></span>
438							<small id="email-help" class="form-hint">For example, name@example.com</small>
439						</div>
440						<div class="field">
441							<label for="message">Message</label>
442							<textarea id="message" name="message" rows="4"></textarea>
443						</div>
444						<button type="submit">Send message</button>
445						<p id="form-status" role="status"></p>
446					</form>
447				</article>
448	
449				<article class="card">
450					<h3>Live Region Example</h3>
451					<p>Click the button to announce a message using a live region. This demonstrates how screen readers are notified of dynamic updates.</p>
452					<button id="announce" type="button">Announce message</button>
453					<div class="live-region" aria-live="polite" aria-atomic="true">
454						<span id="live-message"></span>
455					</div>
456				</article>
457			</section>
458	
459			<section aria-labelledby="resources">
460				<h2 id="resources">Resources</h2>
461				<p>Want to learn more about web accessibility and semantic HTML? Check out these resources:</p>
462				<ul>
463					<li><a href="https://www.w3.org/WAI/WCAG22/quickref/" target="_blank" rel="noopener noreferrer">WCAG 2.2 Quick Reference<span class="visually-hidden"> (opens in new tab)</span></a></li>
464					<li><a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener noreferrer">HTML Living Standard<span class="visually-hidden"> (opens in new tab)</span></a></li>
465					<li><a href="https://www.a11y-101.com/" target="_blank" rel="noopener noreferrer">A11y 101<span class="visually-hidden"> (opens in new tab)</span></a></li>
466				</ul>
467			</section>
468		</main>
469		<footer>
470			<nav aria-label="Footer links">
471				<ul>
472					<li><a href="#top">Back to top</a></li>
473					<li><a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub<span class="visually-hidden"> (opens in new tab)</span></a></li>
474				</ul>
475			</nav>
476			<p><small>&copy; <time datetime="2026">2026</time>. All rights reserved.</small></p>
477		</footer>
478		<script>
479			const messages = [
480				"This update was announced to screen readers!",
481				"Dynamic content updates work with aria-live regions.",
482				"Live regions are essential for accessible web apps.",
483				"Try this with a screen reader like NVDA or JAWS!"
484			];
485			let nextMessage = 0;
486			const announceBtn = document.getElementById('announce');
487			const contactForm = document.getElementById('contact-form');
488			const emailInput = document.getElementById('email');
489			const formStatus = document.getElementById('form-status');
490	
491			if (announceBtn) {
492				announceBtn.addEventListener('click', () => {
493					document.getElementById('live-message').textContent = messages[nextMessage];
494					nextMessage = (nextMessage + 1) % messages.length;
495				});
496			}
497	
498			if (contactForm) {
499				const emailError = document.getElementById('email-error');
500	
501				const validateEmail = () => {
502					let message = '';
503					if (emailInput.validity.valueMissing) {
504						message = 'Enter your email address.';
505					} else if (!emailInput.validity.valid) {
506						message = 'Enter an email address in the format name@example.com.';
507					}
508					emailError.textContent = message;
509					if (message) {
510						emailInput.setAttribute('aria-invalid', 'true');
511						emailInput.setAttribute('aria-describedby', 'email-error email-help');
512					} else {
513						emailInput.removeAttribute('aria-invalid');
514						emailInput.setAttribute('aria-describedby', 'email-help');
515					}
516					return !message;
517				};
518	
519				emailInput.addEventListener('blur', () => {
520					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
521						validateEmail();
522					}
523				});
524	
525				emailInput.addEventListener('input', () => {
526					if (emailInput.hasAttribute('aria-invalid')) {
527						validateEmail();
528					}
529				});
530	
531				contactForm.addEventListener('submit', (event) => {
532					event.preventDefault();
533					formStatus.textContent = '';
534					if (!validateEmail()) {
535						emailInput.focus();
536						return;
537					}
538					contactForm.reset();
539					setTimeout(() => {
540						formStatus.textContent = "Thanks! This is a demo, so nothing was sent.";
541					}, 100);
542				});
543			}
544		</script>
545	</body>
546	</html>
